        correctAnswer: "D",
        solution: "V1 = 8 - 5 = 3V across Rs. Current through load resistor I = 5mA. Maximum current through Zener diode Iz max = 2mA, minimum Iz min = 0. Therefore Is max = 5 + 2 = 7mA. Rs min = 3V/7mA = 3/7 kΩ. Similarly Rs max = 3V/5mA = 3/5 kΩ. Therefore 3/7 kΩ < Rs < 3/5 kΩ.",
